extern void
msh_SurfMeshSetParamd(msh_SurfMesh* p, Vint type, Vdouble param)
{
    static Vchar func[] = "msh_SurfMeshSetParamd";

    if (type == VIS_MESH_EDGELENGTH) {
        if (param <= 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->edgelen = param;
    }
    else if (type == VIS_MESH_MINEDGELENGTH) {
        if (param < 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->minedgelen = param;
    }
    else if (type == VIS_MESH_MAXEDGELENGTH) {
        if (param < 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxedgelen = param;
    }
    else if (type == VIS_MESH_SPANANGLE) {
        if (param <= 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->spanang = param;
        p->cspanang = cos(DEG2RAD(p->spanang));
        p->cspanang2 = cos(DEG2RAD(.5 * p->spanang));
    }
    else if (type == VIS_MESH_MINANGLE) {
        if (param < 0. || param > 60.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->minang = param;
        p->sminang = sin(DEG2RAD(p->minang));
    }
    else if (type == VIS_MESH_MAXANGLE) {
        if (param < 0. || param > 180.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxang = param;
    }
    else if (type == VIS_MESH_MAXWARPANGLE) {
        if (param < 0. || param > 180.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxwarpang = param;
    }
    else if (type == VIS_MESH_MAXSKEWANGLE) {
        if (param < 0. || param > 90.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxskewang = param;
    }
    else if (type == VIS_MESH_MAXEDGEALT) {
        if (param <= 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxedgealt = param;
    }
    else if (type == VIS_MESH_MAXQUADANGLE) {
        if (param < 90.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->maxquadang = param;
    }
    else if (type == VIS_MESH_GROWTHRATE) {
        if (param <= 1.001) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->growthrate = param;
    }
    else if (type == VIS_MESH_CHORDHEIGHT) {
        if (param < 0.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->chordheight = param;
    }
    else if (type == VIS_MESH_MINFEATLENGTH) {
        p->minfeatlen = param;
    }
    else if (type == VIS_MESH_MINFEATANGLE) {
        p->minfeatang = param;
    }
    else if (type == VIS_MESH_MINHEALLENGTH) {
        p->minheallen = param;
    }
    else if (type == VIS_MESH_MINHEALANGLE) {
        p->minhealang = param;
    }
    else if (type == VIS_MESH_MAPANGLE) {
        p->mapangle = param;
    }
    else if (type == VIS_MESH_UNCONNECTLENGTH) {
        p->unconnectlen = param;
    }
    else if (type == VIS_MESH_MAXPROXRATIO) {
        p->maxproxratio = param;
    }
    else if (type == SURFMESH_LOADCENTERX) {
        p->centex[0] = param;
    }
    else if (type == SURFMESH_LOADCENTERY) {
        p->centex[1] = param;
    }
    else if (type == SURFMESH_LOADCENTERZ) {
        p->centex[2] = param;
    }
    else if (type == SURFMESH_LOADLENGTH) {
        p->clenex = param;
    }
    else if (type == SURFMESH_MATELENGTH) {
        p->matelen = param;
    }
    else if (type == SURFMESH_MINSINGANG) {
        p->minsingang = param;
    }
    else if (type == SURFMESH_PRESNODEANGLE) {
        p->presnodeang = param;
    }
    else if (type == SURFMESH_PRESEDGEANGLE) {
        p->presedgeang = param;
    }
    else if (type == VIS_MESH_REFINEFACTOR) {
        if (param != 0. && param <= 1.) {
            p->ierr = SYS_ERROR_VALUE;
            HANDLEERR1(func, p->ierr, "param= %e", param);
            return;
        }
        p->refinefactor = param;
    }
    else {
        p->ierr = SYS_ERROR_ENUM;
        HANDLEERR1(func, p->ierr, "type= %d", type);
        return;
    }
}

