    /*----------------------------------------------------------------------
                          free structures
    ----------------------------------------------------------------------*/
    static void msh_SurfMesh_Free(msh_SurfMesh * p)
    {
        Vint i;
        /* destroy objects */
        if (p->ce) {
            vis_ConnectEnd(p->ce);
            p->ce = NULL;
        }
        if (p->gp != NULL)
            vis_GroupEnd(p->gp);
        p->gp = NULL;
        if (p->gpr != NULL)
            vis_GroupEnd(p->gpr);
        p->gpr = NULL;
        if (p->gt != NULL)
            vis_GroupEnd(p->gt);
        p->gt = NULL;
        if (p->gtm != NULL) {
            vis_GroupEnd(p->gtm);
            p->gtm = NULL;
        }
        if (p->gr != NULL) {
            vis_GroupEnd(p->gr);
            p->gr = NULL;
        }
        if (p->gq != NULL) {
            vis_GroupEnd(p->gq);
            p->gq = NULL;
        }
        if (p->gnf != NULL) {
            vis_GroupEnd(p->gnf);
            p->gnf = NULL;
        }
        if (p->gef) {
            vis_GroupEnd(p->gef);
            p->gef = NULL;
        }
        if (p->spnt != NULL) {
            vut_freeMem(p->spnt);
            p->spnt = NULL;
        }
        if (p->stri != NULL) {
            vut_freeMem(p->stri);
            p->stri = NULL;
        }
        if (p->dselem != NULL) {
            vut_freeMem(p->dselem);
            p->dselem = NULL;
            vis_MeshSizeEnd(p->dmeshsize);
            p->dmeshsize = NULL;
        }
        if (p->btri != NULL) {
            vut_freeMem(p->btri);
            p->btri = NULL;
        }
        if (p->conictri != NULL) {
            vut_freeMem(p->conictri);
            p->conictri = NULL;
        }
        if (p->leftlist != NULL) {
            vsy_ListForEach(p->leftlist, (Vfunc1*)vis_AssocEnd);
            vsy_ListEnd(p->leftlist);
            p->leftlist = NULL;
        }
        if (p->tvhash != NULL) {
            vsy_VHashTableEnd(p->tvhash);
            p->tvhash = NULL;
        }
        if (p->tphash != NULL) {
            vsy_HashTableEnd(p->tphash);
            p->tphash = NULL;
        }
        if (p->hnhash != NULL) {
            vsy_HashTableEnd(p->hnhash);
            p->hnhash = NULL;
        }
        if (p->cnhash != NULL) {
            vsy_HashTableEnd(p->cnhash);
            p->cnhash = NULL;
        }
        if (p->szhash != NULL) {
            vsy_HashTableEnd(p->szhash);
            p->szhash = NULL;
        }
        p->szhash = NULL;
        if (p->edlist != NULL) {
            vsy_ListEnd(p->edlist);
            vsy_ListEnd(p->ixlist);
        }
        p->edlist = NULL;
        p->ixlist = NULL;
        if (p->mslist != NULL) {
            vsy_ListEnd(p->mslist);
            p->mslist = NULL;
        }
        if (p->tplist != NULL) {
            vsy_ListForEach(p->tplist, (Vfunc1*)msh_SurfMesh_TPEnd);
            vsy_ListEnd(p->tplist);
        }
        p->numtp = 0;
        p->tplist = NULL;
        if (p->aconcat != NULL) {
            vsy_ConcatEnd(p->aconcat);
            p->aconcat = NULL;
        }
        if (p->meshsize != NULL) {
            vis_MeshSizeEnd(p->meshsize);
            p->meshsize = NULL;
        }
        /* delete any previous meshcon objects */
        if (p->idtranmg) {
            vis_IdTranEnd(p->idtranmg);
            p->idtranmg = NULL;
        }
        if (p->meshgeo) {
            vis_MeshConEnd(p->meshgeo);
            p->meshgeo = NULL;
        }
        if (p->meshcon) {
            vis_MeshConEnd(p->meshcon);
            p->meshcon = NULL;
        }
        if (p->meshqual) {
            msh_MeshQualEnd(p->meshqual);
            p->meshqual = NULL;
        }
        if (p->meshquad) {
            msh_MeshQuadEnd(p->meshquad);
            p->meshquad = NULL;
        }
        if (p->ivelem) {
            vsy_IntVecEnd(p->ivelem);
            p->ivelem = NULL;
        }
        if (p->intstack) {
            vsy_IntStackEnd(p->intstack);
            p->intstack = NULL;
        }
        for (i = 0; i < VIS_MAXASSOC; i++) {
            if (p->plattr[i] != NULL) {
                vut_freeMem(p->plattr[i]);
            }
            p->plattr[i] = NULL;
        }
        if (p->ptint != NULL) {
            vut_freeMem(p->ptint);
            p->ptint = NULL;
        }
        if (p->ptlist != NULL) {
            vsy_ListForEach(p->ptlist, (Vfunc1*)vis_CoordSysEnd);
            vsy_ListEnd(p->ptlist);
            p->ptlist = NULL;
        }
        if (p->ptfeat != NULL) {
            vut_freeMem(p->ptfeat);
            p->ptfeat = NULL;
        }
        if (p->ptmap != NULL) {
            vut_freeMem(p->ptmap);
            p->ptmap = NULL;
        }
        if (p->pslock != NULL) {
            vut_freeMem(p->pslock);
            p->pslock = NULL;
        }
        if (p->ptc != NULL) {
            vut_freeMem(p->ptncorn);
            vut_freeMem(p->ptcorn);
            vut_freeMem(p->ptcsize);
            vut_freeMem(p->ptcpntr);
            for (i = 0; i < p->numpt; i++) {
                if (p->ptc[i]) {
                    vut_freeMem(p->ptc[i]);
                }
            }
            vut_freeMem(p->ptc);
        }

        if (p->pscurr != NULL) {
            vut_freeMem(p->pscurr);
            vut_freeMem(p->pstarg);
            vut_freeMem(p->psskip);
            vut_freeMem(p->pesnum);
            p->pscurr = NULL;
            p->pstarg = NULL;
            p->psskip = NULL;
            p->pesnum = NULL;
        }
        if (p->pntunconnect != NULL) {
            vsy_BitVecEnd(p->pntunconnect);
            p->pntunconnect = NULL;
        }
        if (p->trinonman != NULL) {
            vsy_BitVecEnd(p->trinonman);
            p->trinonman = NULL;
        }
        if (p->tripenetrate != NULL) {
            vsy_BitVecEnd(p->tripenetrate);
            p->tripenetrate = NULL;
        }
        if (p->trifreeedge != NULL) {
            vsy_BitVecEnd(p->trifreeedge);
            p->trifreeedge = NULL;
        }
        if (p->triintersect != NULL) {
            vsy_BitVecEnd(p->triintersect);
            p->triintersect = NULL;
        }
        if (p->triintersectpair != NULL) {
            vis_IdTranEnd(p->triintersectpair);
            p->triintersectpair = NULL;
        }
        if (p->pntunpurged != NULL) {
            vsy_BitVecEnd(p->pntunpurged);
            p->pntunpurged = NULL;
        }
    }

    extern void msh_SurfMeshComputeTriPair(msh_SurfMesh * p, Vdouble xmas[3], Vdouble vmas[3], Vdouble xrot[3], Vdouble vrot[3],
                                           Vdouble ang)
    {
        static Vchar func[] = "msh_SurfMeshComputeTriPair";
        Vint i, j, n;
        Vint numpnts, numtris;
        Vint ix[3], eflag[3], pflag[3], itri, npface, aid, imas, islv, nslv;
        Vint ixs[3], eflags[3], pflags[3];
        Vint mtri, stri, jm, it, its, js, ipair, npair;
        vsy_IntHash* inthash;
        vsy_IntVec *intvec, *intvecslv;
        Vdouble extent[2][3];
        Vdouble d[3], d1[3], d2[3], fl, xtol, vtol;
        Vdouble x[3][3], xs[3][3], vs[3];
        Vdouble xslv[3], vslv[3], sensem, senses, sense;
        Vdouble tm[3][3], angd, metric, angh, tmh[3][3], vh[3], vr[3], vm[3];
        Vdouble xtm[3], vtm[3], xts[3], vts[3];
        Vint ierr;

        vis_ConnectExtentdv(p->ce, NULL, extent);
        DIFF3(extent[0], extent[1], d);
        fl = MAG3(d);
        xtol = .000001 * fl;
        vtol = .99999;

        MOVE3(vrot, vr);
        UNIT3(vr);
        MOVE3(vmas, vm);
        UNIT3(vm);
        /* compute rotation matrix to slave surface */
        angd = DEG2RAD(ang);
        vml_dircos3vectordv(tm, vr, angd, &ierr);
        if (ierr) {
            printf("improper rotation specified\n");
            return;
        }
        /* compute point on slave and normal */
#ifdef VISMESH_DEBUG
        printf("xmas= %f %f %f\n", xmas[0], xmas[1], xmas[2]);
        printf("vmas= %f %f %f\n", vmas[0], vmas[1], vmas[2]);
#endif
        DIFF3(xmas, xrot, d);
        MATVEC3(tm, d, d1);
        SUM3(d1, xrot, xslv);
        MATVEC3(tm, vm, vslv);
#ifdef VISMESH_DEBUG
        printf("xslv= %f %f %f\n", xslv[0], xslv[1], xslv[2]);
        printf("vslv= %f %f %f\n", vslv[0], vslv[1], vslv[2]);
#endif
        /* half plane normal into master */
        angh = .5 * angd;
        vml_dircos3vectordv(tmh, vr, angh, &ierr);
        MATVEC3(tmh, vm, vh);
        fl = DOT3(vh, d);
        SCALE3(vh, fl);
        UNIT3(vh);
        /* hashtable, key = face, value = marked tri */
        inthash = vsy_IntHashBegin();
        /* vector, key = ith detected face, value = face */
        intvec = vsy_IntVecBegin();
        intvecslv = vsy_IntVecBegin();
        npface = 0;
        nslv = 0;
        msh_SurfMeshInq(p, &numpnts, &numtris);
        /* find triangle markers on master geometry faces */
        /* make a list of triangles on slave surface */
        for (i = 1; i <= numtris; i++) {
            msh_SurfMeshGetTri(p, i, ix, eflag);
            /* master face already marked */
            msh_SurfMeshGetTriAssoc(p, VIS_GEOFACE, i, SYS_FACE, 1, &aid);
            if (aid) {
                vsy_IntHashLookup(inthash, aid, &itri);
                if (itri)
                    continue;
            }
            /* gather triangle point data */
            /* check for points on master face geometry */
            /* check for points on slave face geometry */
            imas = 1;
            islv = 1;
            for (j = 0; j < 3; j++) {
                msh_SurfMeshGetPoint(p, ix[j], x[j], &pflag[j]);
            }
            /* check points */
            for (j = 0; j < 3; j++) {
                DIFF3(x[j], xrot, d);
                /* point on axis check */
                fl = MAG3(d);
                if (fl < xtol) {
                    continue;
                }
                UNIT3(d);
                fl = DOT3(vr, d);
                if (fabs(fl) > vtol) {
                    continue;
                }
                /* half space check */
                fl = DOT3(vh, d);
                if (fl < 0.) {
                    imas = 0;
                }
                else if (fl > 0.) {
                    islv = 0;
                }
                /* point on surface check */
                DIFF3(x[j], xmas, d);
                fl = DOT3(d, vm);
                if (fabs(fl) > xtol) {
                    imas = 0;
                }
                DIFF3(x[j], xslv, d);
                fl = DOT3(d, vslv);
                if (fabs(fl) > xtol) {
                    islv = 0;
                }
            }
            /* add to slave face list */
            if (imas == 0 && islv == 0)
                continue;
            /* avoid very bad triangles */
            vis_computeMetricTriangle(NULL, x, &metric);
            if (metric < 1.e-10)
                continue;
            /* select tri with preserved node connected to preserved edge */
            /* record slave triangle */
            for (j = 0; j < 3; j++) {
                if (pflag[j] && (eflag[j] || eflag[(j + 2) % 3])) {
                    DIFF3(x[j], xrot, d);
                    /* point on axis check */
                    fl = MAG3(d);
                    if (fl < xtol) {
                        continue;
                    }
                    UNIT3(d);
                    fl = DOT3(vr, d);
                    if (fabs(fl) > vtol) {
                        continue;
                    }
                    if (imas) {
                        vsy_IntHashInsert(inthash, aid, i);
                        npface += 1;
                        vsy_IntVecSet(intvec, npface, aid);
                    }
                    else if (islv) {
                        nslv += 1;
                        vsy_IntVecSet(intvecslv, nslv, i);
                    }
                    break;
                }
            }
            /* determine sense of master face triangles by testing first */
            if (imas && npface == 1) {
                DIFF3(x[1], x[0], d1);
                DIFF3(x[2], x[0], d2);
                CROSS3(d1, d2, d);
                sensem = DOT3(d, vm);
            }
            /* determine sense of slave face triangles by testing first */
            if (islv && nslv == 1) {
                DIFF3(x[1], x[0], d1);
                DIFF3(x[2], x[0], d2);
                CROSS3(d1, d2, d);
                senses = DOT3(d, vslv);
            }
        }
#ifdef VISMESH_DEBUG
        /* print master faces and triangle markers */
        printf("number of master faces= %d\n", npface);
        printf("master sense= %f\n", sensem);
        for (n = 1; n <= npface; n++) {
            vsy_IntVecGet(intvec, n, &aid);
            vsy_IntHashLookup(inthash, aid, &itri);
            printf("master face= %d, triangle marker= %d\n", aid, itri);
        }
        printf("number of slave triangles= %d\n", nslv);
        printf("slave sense= %f\n", senses);
        vsy_IntVecPrint(intvecslv);
#endif
        /* slave face sense relative to master face */
        sense = sensem * senses;
        if (sense > 0.) {
            sense = 1.;
        }
        else {
            sense = -1.;
        }
        /* match master face triangle markers with slave face */
        npair = 0;
        for (n = 1; n <= npface; n++) {
            vsy_IntVecGet(intvec, n, &aid);
            vsy_IntHashLookup(inthash, aid, &mtri);
            msh_SurfMeshGetTri(p, mtri, ix, eflag);
            for (j = 0; j < 3; j++) {
                msh_SurfMeshGetPoint(p, ix[j], x[j], &pflag[j]);
            }
            jm = -1;
            for (j = 0; j < 3; j++) {
                if (pflag[j] && (eflag[j] || eflag[(j + 2) % 3])) {
                    if (eflag[j]) {
                        it = 0;
                        DIFF3(x[(j + 1) % 3], x[j], vtm);
                    }
                    else {
                        it = 1;
                        DIFF3(x[j], x[(j + 2) % 3], vtm);
                    }
                    /* matching point */
                    MOVE3(x[j], xtm);
                    DIFF3(xtm, xrot, d);
                    MATVEC3(tm, d, d1);
                    SUM3(d1, xrot, xts);
                    /* make sure the matching point is not on the axis */
                    DIFF3(xtm, xts, d);
                    fl = MAG3(d);
                    if (fl < xtol)
                        continue;
                    /* matching edge tangent */
                    UNIT3(vtm);
                    MATVEC3(tm, vtm, vts);
                    SCALE3(vts, sense);
                    jm = j;
                    break;
                }
            }
#ifdef VISMESH_DEBUG
            printf("master tri= %d, jm= %d\n", mtri, jm);
            printf("xtm= %f %f %f\n", xtm[0], xtm[1], xtm[2]);
            printf("vtm= %f %f %f\n", vtm[0], vtm[1], vtm[2]);
            printf("xts= %f %f %f\n", xts[0], xts[1], xts[2]);
            printf("vts= %f %f %f\n", vts[0], vts[1], vts[2]);
#endif
            if (jm == -1) {
                p->ierr = SYS_ERROR_OPERATION;
                HANDLEERR1(func, p->ierr, "Master node not found tri= %d", mtri);
                continue;
            }
            if (sense > 0.) {
                its = it;
            }
            else {
                its = 1 - it;
            }
            /* loop through triangles on slave surface */
            for (i = 1; i <= nslv; i++) {
                vsy_IntVecGet(intvecslv, i, &stri);
                msh_SurfMeshGetTri(p, stri, ixs, eflags);
                ipair = 0;
                for (j = 0; j < 3; j++) {
                    msh_SurfMeshGetPoint(p, ixs[j], xs[j], &pflags[j]);
                }
                for (j = 0; j < 3; j++) {
                    DIFF3(xs[j], xts, d);
                    fl = MAG3(d);
                    /* test edges connected to match point */
                    if (fl < xtol) {
                        if (its == 0) {
                            if (eflags[j] == 0)
                                continue;
                            DIFF3(xs[(j + 1) % 3], xs[j], vs);
                        }
                        else {
                            if (eflags[(j + 2) % 3] == 0)
                                continue;
                            DIFF3(xs[j], xs[(j + 2) % 3], vs);
                        }
                        UNIT3(vs);
                        fl = DOT3(vs, vts);
                        if (fl > .995) {
                            js = j;
                            ipair = 1;
                            break;
                        }
                    }
                }
                /* enter triangle pair for face */
                if (ipair) {
                    npair += 1;
#ifdef VISMESH_DEBUG
                    printf("tripair, idm= %d, nom= %d, ids= %d, nos= %d, sense= %f\n", mtri, jm + 1, stri, js + 1, sense);
#endif
                    msh_SurfMeshSetTriPair(p, SYS_FACE, mtri, jm + 1, stri, js + 1, sense);
                    break;
                }
            }
        }
#ifdef VISMESH_DEBUG
#endif
        printf("number of master faces= %d\n", npface);
        printf("number of tripairs    = %d\n", npair);
        /* delete objects */
        vsy_IntHashEnd(inthash);
        vsy_IntVecEnd(intvec);
        vsy_IntVecEnd(intvecslv);
    }
